        height: 100%;
        text-align: center;
        image-rendering: pixelated;
    }

    .playerIcon,
    .monster,
    .item{
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        pointer-events:none;
    }
    
    .agentJoystick button {
        font-size: 30px;
        padding: 10px;
        border-radius: 8px;
        border: 2px solid #8b6f47;
        background: #ffe4b5;
        cursor: pointer;
    }

    .agentJoystick button:hover {
        background: #ffcc80;
    }

    .gameStatus {
        padding: 10px;
        margin: 10px 0;
        border: 3px solid #8b6f47;
        border-radius: 8px;
        background-color: #fff8dc;
        font-weight: bold;
        text-align: center;
        font-size: 18px;
    }

    .gameStatus.won {
        background-color: #c1f0c1;
        color: #006400;
    }

    .gameStatus.lost {
        background-color: #ffd6d6;
        color: #990000;
    }

    .score, .floorInfo {
        padding: 6px;
        margin: 5px 0;
        border: 2px solid #8b6f47;
        border-radius: 6px;
        background-color: #fffaf0;
        font-weight: bold;
        text-align: center;
    }

    .btnReset {
        padding: 8px 16px;
        margin: 5px 0;
        font-size: 14px;
        font-weight: bold;
        background-color: #ffcc80;
        border: 2px solid #8b6f47;
        border-radius: 6px;
        cursor: pointer;
    }

    .btnReset:hover {
        background-color: #ffb347;
    }
    
    /* STYLE CHO CÁC Ô MAP */
    .wall { background: #5c4033; }
    
    /* TƯỜNG MỀM (Tường Nứt - Cell 12): Có vết nứt chữ X và viền đứt đoạn */
    .softWall { 
        background-color: #8d6e63; 
        background-image: 
            linear-gradient(45deg, transparent 44%, #3e2723 46%, #3e2723 54%, transparent 56%),
            linear-gradient(-45deg, transparent 44%, #3e2723 46%, #3e2723 54%, transparent 56%);
        border: 2px dashed #4a332a !important; 
    }

    .hole { background: #ffb3b3; }
    .door { background: #f2d2a2; }
    .stairsUp { background: #add8e6; }
    .entry { background: #87cefa; }
    .goal { background: #90ee90; }
    .monsterChasing { background-color: #ff4d4d !important; }
    .playerShield{ background: #4da6ff; }    
    .monsterStunned{
        background: repeating-linear-gradient(
        45deg,
        #cbb3ff,
        #cbb3ff 5px,
        #a38cff 5px,
        #a38cff 10px
    );}
    .monsterSpawn{
        background:#e6ccff;
    }

    .playerIcon{
        font-size: 24px;
        z-index: 3;
    }
    .monster{
        font-size: 22px;
        z-index: 2;
    }
    .item{
        font-size:20px;
        z-index: 1;
    }
    
    .heart{
        color:#ddd;
    }
    
    .heartFull{
        color:red;
    }
    
    .agentJoystick button.hammerReady{
        background:#cfd8dc;
    }
    .agentJoystick button.hammerCooldown{
        background:#ffb3b3;
    }
    .agentJoystick button.hammerReady:hover{
        background:#b0bec5;
    }
    .agentJoystick button.hammerCooldown:hover{
        background:#ff9999;
    }

    .stunIcon{
        position:absolute;
        bottom:1px;
        right:1px;
        font-size:11px;
        line-height:1;
        z-index:4;
        background:#6a5acd;
        color:white;
        border-radius:3px;
        padding:0 2px;
    }
    
    .partialHidden .monster,
    .partialHidden .item,
    .partialHidden .stunIcon{
        display:none !important;
    }
    .partialHidden .playerIcon{
        display:block;
    }
    .partialHidden{
        background:#111 !important;
    }
</style>



<div class="container" ng-if="ui">
    <div class="row">
        <div class="col-md-12">
            <div class="score">Điểm số: {{ui.score | number:1}}</div>
            
            <div class="floorInfo">
                Tầng: {{ui.floor}} |
                HP:
                <span class="hpContainer">
                    <span class="heart" ng-class="{'heartFull': ui.hp>=1}">❤</span>
                    <span class="heart" ng-class="{'heartFull': ui.hp>=2}">❤</span>
                    <span class="heart" ng-class="{'heartFull': ui.hp>=3}">❤</span>
                </span>
                | Chìa khóa: {{ui.key==1?'Có':'Không'}} | Shield: {{ui.shield}} 🛡️ | Bước: {{ui.stepCount}}/{{ui.maxSteps}} | Reward bước trước: {{ui.lastReward}}
            </div>
            
            <div class="floorInfo" style="background-color: #e3f2fd;">
                Búa: <span ng-class="{'text-success': ui.hammerTimer == 0, 'text-danger': ui.hammerTimer > 0}" style="font-weight: bold;">
                    {{ui.hammerTimer == 0 ? 'Sẵn sàng 🔨' : 'Đang hồi (' + ui.hammerTimer + ' bước)'}}
                </span>
            </div>
            
            <div class="gameStatus"
                 ng-class="{
                   'won': gameStatus && gameStatus.indexOf('thắng') !== -1,
                   'lost': gameStatus && gameStatus !== 'Đang chơi' && gameStatus.indexOf('thắng') === -1
                 }">
                 {{gameStatus}}
            </div>
            
        </div>
    </div>
    
    <div class="row">
        <div class="col-md-12">
            <div class="boardContainer">
                <div class="boardRow" ng-repeat="(i, row) in ui.board track by i">
                    <div class="boardCell"
                        ng-repeat="(j, cell) in row track by j"
                        ng-init="cellKey = i + ',' + j;">
                        
                        <div class="cell"
                             ng-class="{
                                'wall': cell==1,
                                'softWall': cell==12,
                                'bomb': cell==3,
                                'hole': cell==4,
                                'blood': cell==5,
                                'door': cell==6,
                                'stairsUp': cell==7,
                                'entry': cell==8,
                                'goal': cell==9,
                                'shield': cell==11,
                                'playerShield': i==ui.pos[1] && j==ui.pos[0] && ui.shield>0,
                                'monsterChasing': ui.monsterChasing && ui.monsterChasing[cellKey],
                                'monsterStunned': ui.monsterStunned && ui.monsterStunned[cellKey],
                                'monsterSpawn': ui.monsterSpawnCells && ui.monsterSpawnCells[cellKey],
                                
                                'partialHidden': partialView &&
                                 !(
                                    (i==ui.pos[1] && j==ui.pos[0]) ||
                                    (i==ui.pos[1]-1 && j==ui.pos[0]) ||
                                    (i==ui.pos[1]+1 && j==ui.pos[0]) ||
                                    (i==ui.pos[1] && j==ui.pos[0]-1) ||
                                    (i==ui.pos[1] && j==ui.pos[0]+1) ||
                                    (i==ui.pos[1]-2 && j==ui.pos[0]) ||
                                    (i==ui.pos[1]+2 && j==ui.pos[0]) ||
                                    (i==ui.pos[1] && j==ui.pos[0]-2) ||
                                    (i==ui.pos[1] && j==ui.pos[0]+2) ||
                                    (i==ui.pos[1]-1 && j==ui.pos[0]-1) ||
                                    (i==ui.pos[1]-1 && j==ui.pos[0]+1) ||
                                    (i==ui.pos[1]+1 && j==ui.pos[0]-1) ||
                                    (i==ui.pos[1]+1 && j==ui.pos[0]+1)
                                  )
                                    
                             }">
                    
                            <label ng-if="i==ui.pos[1] && j==ui.pos[0]" class="playerIcon">🧙</label>

                            <label class="monster" ng-if="ui.monsterCells[cellKey] && !(i==ui.pos[1] && j==ui.pos[0])">👹</label>
                            
                            <label class="stunIcon"
                                   ng-if="ui.monsterStunSteps[cellKey] && ui.monsterStunSteps[cellKey] > 0">
                                   {{ui.monsterStunSteps[cellKey]}}
                            </label>

                            <label class="item" ng-if="cell==2 && !(i==ui.pos[1] && j==ui.pos[0])">🔑</label>
                            <label class="item" ng-if="cell==3 && !(i==ui.pos[1] && j==ui.pos[0])">💣️</label>
                            <label class="item" ng-if="cell==4 && !(i==ui.pos[1] && j==ui.pos[0])">🕳️</label>
                            <label class="item" ng-if="cell==5 && !(i==ui.pos[1] && j==ui.pos[0])">❤️</label>
                            <label class="item" ng-if="cell==6 && !(i==ui.pos[1] && j==ui.pos[0])">🚪</label>
                            <label class="item" ng-if="cell==7 && !(i==ui.pos[1] && j==ui.pos[0])">⏫</label>
                            <label class="item" ng-if="cell==8 && !(i==ui.pos[1] && j==ui.pos[0])">🌀</label>
                            <label class="item" ng-if="cell==9 && !(i==ui.pos[1] && j==ui.pos[0])">👑</label>
                            <label class="item" ng-if="cell==11 && !(i==ui.pos[1] && j==ui.pos[0])">🛡️</label>
                        </div>
                    </div>
                </div>
            </div>
            
            <div style="margin-top:6px; padding-left:2px;">
                <label style="font-size:13px; cursor:pointer;">
                    <input type="checkbox" ng-model="partialView">
                    Partial View
                </label>
            </div>
        </div>
    </div>
</div>
